ARCHIVE;

    public function run(): void
    {
        $responses = json_decode(self::RESPONSES_JSON, true, 512, JSON_THROW_ON_ERROR);
        if (! is_array($responses) || count($responses) !== 46) {
            throw new RuntimeException('L’export intégré doit contenir 46 réponses.');
        }

        $archive = base64_decode(preg_replace('/\s+/', '', self::ARCHIVE_BASE64), true);
        if ($archive === false || hash('sha256', $archive) !== self::ARCHIVE_SHA256) {
            throw new RuntimeException('L’archive Word intégrée est invalide.');
        }

        $temporary = tempnam(sys_get_temp_dir(), 'geves-eau-');
        if ($temporary === false || file_put_contents($temporary, $archive) !== strlen($archive)) {
            throw new RuntimeException('Impossible de préparer l’archive Word intégrée.');
        }

        $zip = new ZipArchive;
        $opened = false;
        try {
            if ($zip->open($temporary) !== true) {
                throw new RuntimeException('Impossible d’ouvrir l’archive Word intégrée.');
            }
            $opened = true;

            $this->validateDocuments($responses, $zip);
            DB::transaction(function () use ($responses, $zip): void {
                $event = $this->event();
                $this->equipe($event);
                $this->applyPosterDetails($event, $this->storePosters($event));
                foreach (self::TRACKS as $order => $track) {
                    Atelier::firstOrCreate(
                        ['event_id' => $event->id, 'title' => $track],
                        ['tracks' => [$track], 'ordre' => $order + 1]
                    );
                }
                $number = 0;

                foreach ($responses as $response) {
                    $user = $this->authorAccount($response);
                    $participant = $this->participant($event, $response);
                    if ($participant->user_id === null) {
                        $participant->update(['user_id' => $user->id]);
                    } elseif ((int) $participant->user_id !== (int) $user->id) {
                        throw new RuntimeException("Le participant de la ligne {$response['row']} est déjà lié à un autre compte.");
                    }
                    foreach ($response['submissions'] as $source) {
                        $number++;
                        $this->submission($event, $participant, $response, $source, $zip, $number);
                    }
                }

                if ($number !== 49) {
                    throw new RuntimeException('L’export intégré doit contenir 49 résumés.');
                }

                $this->command?->info('Colloque Eau au Togo : 46 comptes auteurs, 46 réponses, 49 résumés et 49 pièces Word importés.');
            });
        } finally {
            if ($opened) {
                $zip->close();
            }
            @unlink($temporary);
        }
    }

    /** @param array<int, array<string, mixed>> $responses */
    private function validateDocuments(array $responses, ZipArchive $zip): void
    {
        $indexes = [];
        foreach ($responses as $response) {
            foreach ($response['submissions'] as $source) {
                $index = (int) $source['file_index'];
                $bytes = $zip->getFromIndex($index);
                if ($bytes === false || hash('sha256', $bytes) !== $source['file_sha256']) {
                    throw new RuntimeException("Pièce Word invalide pour le fichier ZIP n° {$index}.");
                }
                $indexes[] = $index;
            }
        }

        sort($indexes);
        if ($indexes !== range(1, 49)) {
            throw new RuntimeException('Les 49 pièces Word doivent être associées une seule fois.');
        }
    }

    /** @return array{primary: string, second_call: string} */
    private function storePosters(Event $event): array
    {
        $posters = [
            'primary' => [
                'path' => EventStorage::artwork($event).'/affiche-colloque.jpeg',
                'title' => 'Affiche du colloque',
                'sha256' => self::POSTER_PRIMARY_SHA256,
                'base64' => self::POSTER_PRIMARY_BASE64,
                'ordre' => 1,
            ],
            'second_call' => [
                'path' => EventStorage::artwork($event).'/affiche-deuxieme-appel.jpeg',
                'title' => 'Deuxième appel à communication',
                'sha256' => self::POSTER_SECOND_CALL_SHA256,
                'base64' => self::POSTER_SECOND_CALL_BASE64,
                'ordre' => 2,
            ],
        ];

        $disk = Storage::disk('public');
        $urls = [];
        foreach ($posters as $key => $poster) {
            $bytes = base64_decode(preg_replace('/\s+/', '', $poster['base64']), true);
            if ($bytes === false || hash('sha256', $bytes) !== $poster['sha256']) {
                throw new RuntimeException("L’affiche {$key} intégrée au seeder est invalide.");
            }

            if (! $disk->exists($poster['path'])) {
                if (! $disk->put($poster['path'], $bytes)) {
                    throw new RuntimeException("Impossible de stocker l’affiche {$key}.");
                }
            } elseif (hash('sha256', (string) $disk->get($poster['path'])) !== $poster['sha256']) {
                throw new RuntimeException("Une affiche différente existe déjà à l’emplacement {$poster['path']}.");
            }

            $urls[$key] = $disk->url($poster['path']);
            $media = Media::firstOrCreate(
                ['event_id' => $event->id, 'url' => $urls[$key]],
                ['type' => 'document', 'title' => $poster['title'], 'ordre' => $poster['ordre']]
            );
            $previousTitle = $poster['title'].' (dates imprimées à corriger)';
            if ($media->title === $previousTitle) {
                $media->update(['title' => $poster['title']]);
            }
        }

        return $urls;
    }

    /** @param array{primary: string, second_call: string} $posterUrls */
    private function applyPosterDetails(Event $event, array $posterUrls): void
    {
        $settings = $event->settings ?? [];
        $originalIntro = 'Premier Colloque Scientifique sur la Problématique de l’Eau au Togo. '
            .'Les résumés sont attendus au plus tard le 15 octobre 2026.';
        if (blank($settings['short_name'] ?? null) || $settings['short_name'] === 'Colloque Eau au Togo 2026') {
            $settings['short_name'] = 'Colloque Eau au Togo';
        }

        if (blank($event->theme) || $event->theme === 'La problématique de l’eau au Togo') {
            $event->theme = self::OFFICIAL_THEME;
        }
        if (blank($event->subtitle)) {
            $event->subtitle = 'Deuxième appel à communication';
        }
        $posterIntro = 'L’Université de Kara organise le Premier Colloque Scientifique sur la Problématique de l’Eau au Togo, '
            .'sous le haut parrainage des ministères chargés de l’enseignement supérieur, de la recherche scientifique, de l’eau et de l’assainissement. '
            .'Thème : '.self::OFFICIAL_THEME.' Les résumés sont attendus au plus tard le 15 octobre 2026. '
            .'Le colloque se tiendra du 11 au 13 novembre 2026 à l’Université de Kara.';
        $previousPosterIntro = str_replace('du 11 au 13 novembre', 'du 10 au 13 novembre', $posterIntro);
        if (blank($settings['intro'] ?? null)
            || $settings['intro'] === $originalIntro
            || $settings['intro'] === $previousPosterIntro) {
            $settings['intro'] = $posterIntro;
        }
        $settings['short_desc'] ??= self::OFFICIAL_THEME;
        if (empty($settings['fees'])) {
            $settings['fees'] = self::OFFICIAL_FEES;
        }

        $dates = $settings['key_dates'] ?? [];
        foreach ([
            ['date' => '2026-05-22', 'label' => 'Lancement de l’appel à communication'],
            ['date' => '2026-10-15', 'label' => 'Date limite de soumission des résumés'],
            ['date' => '2026-10-16', 'label' => 'Notification d’acceptation des résumés'],
            ['date' => '2026-11-11', 'label' => 'Début du colloque'],
            ['date' => '2026-11-13', 'label' => 'Fin du colloque'],
        ] as $officialDate) {
            if (! in_array($officialDate['label'], array_column($dates, 'label'), true)) {
                $dates[] = $officialDate;
            }
        }
        $settings['key_dates'] = $dates;

        $submissionForm = $settings['submission_form'] ?? [];
        $rules = $submissionForm['rules'] ?? [];
        if (! isset($rules['word_limit']) || (int) $rules['word_limit'] === 300) {
            $rules['word_limit'] = 250;
        }
        $submissionForm['rules'] = $rules;
        $submissionForm['fields']['keywords']['separator'] ??= 'both';
        if (($submissionForm['fields']['keywords']['help'] ?? null) === 'Séparés par des virgules') {
            $submissionForm['fields']['keywords']['help'] = 'Séparez les mots-clés par une virgule ou un point-virgule.';
        }
        $submissionForm['fields']['abstract']['help'] ??= 'Résumé de 250 mots maximum.';
        $submissionForm['fields']['file']['help'] ??= 'Respectez le template du colloque : Times New Roman 12, interligne simple.';
        $settings['submission_form'] = $submissionForm;

        $settings['posters'] = [
            ['title' => 'Affiche du colloque', 'url' => $posterUrls['primary'], 'sha256' => self::POSTER_PRIMARY_SHA256],
            ['title' => 'Deuxième appel à communication', 'url' => $posterUrls['second_call'], 'sha256' => self::POSTER_SECOND_CALL_SHA256],
        ];
        $settings['poster_source'] = [
            'submission_url' => 'https://forms.gle/Rj4b7PUggn9XyU5E8',
            'printed_event_dates' => '11-13 novembre 2026',
            'confirmed_event_dates' => '11-13 novembre 2026',
        ];
        $settings['practical']['venue'] ??= 'Université de Kara, Kara, Togo';
        $settings['practical']['contacts'] ??= 'colloque_eau_uk@univkara.tg - +228 92168064 / 90721274 / 90212606';

        if ($settings !== ($event->settings ?? [])) {
            $event->settings = $settings;
        }
        if ($event->isDirty()) {
            $event->save();
        }
    }

    /**
     * Installe le gestionnaire et le co-gestionnaire du colloque.
     *
     * ⚠️ Aucun mot de passe connu n'est posé : le compte s'ouvre par
     * réinitialisation, comme les comptes auteurs de cet import. Poser un mot de
     * passe choisi ici le mettrait en clair dans le dépôt.
     *
     * ⚠️ Idempotent : un compte déjà présent est réutilisé (la personne peut
     * figurer parmi les auteurs), et une fonction déjà attribuée n'est pas
     * dupliquée. Le seeder se rejoue.
     */
    private function equipe(Event $event): void
    {
        foreach (self::TEAM as $membre) {
            if (! Role::query()->where('guard_name', 'web')->where('name', $membre['role'])->exists()) {
                throw new RuntimeException(
                    "Le rôle « {$membre['role']} » n’existe pas : lancez `php artisan db:seed` "
                    .'(RolesAndAdminSeeder) avant d’importer le colloque.'
                );
            }

            $email = mb_strtolower($membre['email']);
            $user = User::query()->whereRaw('LOWER(email) = ?', [$email])->first();

            if ($user === null) {
                $user = new User;
                $user->forceFill([
                    'name' => trim($membre['given_name'].' '.$membre['surname']),
                    'first_name' => $membre['given_name'],
                    'last_name' => $membre['surname'],
                    'email' => $email,
                    'password' => Str::password(48),
                    'must_reset_password' => true,
                    'is_active' => true,
                    // « Administrateur de colloque » : crée et gère des
                    // colloques, sans voir ceux où il n'est pas affecté.
                    'access_level' => User::ACCESS_COLLOQUE_ADMIN,
                    'meta' => ['import_source' => self::SOURCE, 'team_role' => $membre['role']],
                ])->save();
            }

            if (! $user->hasRole($membre['role'])) {
                $user->assignRole($membre['role']);
            }

            $deja = DB::table('event_user')
                ->where('event_id', $event->id)
                ->where('user_id', $user->id)
                ->where('role', $membre['role'])
                ->exists();

            if (! $deja) {
                $event->team()->attach($user->id, ['role' => $membre['role']]);
            }
        }
    }

    private function event(): Event
    {
        $series = EventSeries::firstOrCreate(
            ['slug' => 'problematique-eau-togo'],
            ['name' => 'Colloque Scientifique sur la Problématique de l’Eau au Togo', 'type' => 'colloque']
        );

        $event = Event::firstOrCreate(
            ['slug' => self::EVENT_SLUG],
            [
                'event_series_id' => $series->id,
                'title' => 'Premier Colloque Scientifique sur la Problématique de l’Eau au Togo',
                'event_label' => 'Premier colloque scientifique',
                'theme' => 'La problématique de l’eau au Togo',
                'year' => 2026,
                'date_start' => '2026-11-11',
                'date_end' => '2026-11-13',
                'location' => 'Université de Kara, Kara, Togo',
                'status' => 'open',
                'submission_open' => now()->lt(Carbon::parse('2026-10-16 00:00:00')),
                'submission_deadline' => '2026-10-15 23:59:59',
                'settings' => [
                    'short_name' => 'Colloque Eau au Togo',
                    'intro' => 'Premier Colloque Scientifique sur la Problématique de l’Eau au Togo. '
                        .'Les résumés sont attendus au plus tard le 15 octobre 2026.',
                    'main_language' => 'Français',
                    'languages' => ['Français'],
                    'format' => 'Présentiel & hybride',
                    'max_communications' => 3,
                    'tracks' => self::TRACKS,
                    'key_dates' => [
                        ['date' => '2026-10-15', 'label' => 'Date limite de soumission des résumés'],
                        ['date' => '2026-11-11', 'label' => 'Début du colloque'],
                        ['date' => '2026-11-13', 'label' => 'Fin du colloque'],
                    ],
                    'contact' => [
                        'email' => 'colloque_eau_uk@univkara.tg',
                        'phone' => '+228 92168064 / 90721274 / 90212606',
                        'address' => 'Université de Kara, Kara, Togo',
                    ],
                ],
            ]
        );

        // La date confirmée par l'organisateur corrige également un import
        // antérieur ; les autres modifications humaines restent intactes.
        $settings = $event->settings ?? [];
        $keyDates = $settings['key_dates'] ?? [];
        $datesChanged = false;
        foreach ($keyDates as &$keyDate) {
            if (($keyDate['label'] ?? null) === 'Début du colloque' && ($keyDate['date'] ?? null) !== '2026-11-11') {
                $keyDate['date'] = '2026-11-11';
                $datesChanged = true;
            }
        }
        unset($keyDate);

        if ($event->date_start?->toDateString() !== '2026-11-11' || $datesChanged) {
            $event->date_start = '2026-11-11';
            if ($datesChanged) {
                $settings['key_dates'] = $keyDates;
                $event->settings = $settings;
            }
            $event->save();
        }

        return $event;
    }

    /** @param array<string, mixed> $source */
    private function participant(Event $event, array $source): Participant
    {
        $rawEmail = trim((string) $source['email']);
        $firstEmail = trim(explode(';', $rawEmail)[0]);
        $email = filter_var($firstEmail, FILTER_VALIDATE_EMAIL) ? mb_strtolower($firstEmail) : '';
        $phone = trim((string) $source['phone']);

        // Pour l'adresse invalide, le téléphone reste la clé de la fiche source.
        $identity = $email !== ''
            ? ['event_id' => $event->id, 'email' => $email]
            : ['event_id' => $event->id, 'phone' => $phone];

        return Participant::firstOrCreate($identity, [
            'first_name' => trim((string) $source['given_name']),
            'last_name' => trim((string) $source['surname']),
            'email' => $email,
            'phone' => $phone,
            'institution' => trim((string) $source['affiliation']),
            'country' => trim((string) $source['country']),
            'title' => trim((string) $source['grade']),
            'role' => 'author',
            'participation_mode' => $source['presentation_mode'] === 'Distantiel' ? 'online' : 'onsite',
            'meta' => [
                'import_source' => self::SOURCE,
                'source_row' => $source['row'],
                'source_email' => $rawEmail,
                'presentation_mode' => $source['presentation_mode'],
                'preferred_payment_method' => $source['preferred_payment_method'],
                'another_abstract_answer' => $source['another_abstract_answer'],
                'another_abstract_answer_2' => $source['another_abstract_answer_2'],
                'submitted_at' => $source['timestamp'],
            ],
            'created_at' => $source['timestamp'],
        ]);
    }

    /** Compte global de l'auteur répondant, sans mot de passe connu du seeder. */
    private function authorAccount(array $source): User
    {
        $rawEmail = trim(explode(';', (string) $source['email'])[0]);
        $validEmail = filter_var($rawEmail, FILTER_VALIDATE_EMAIL) ? mb_strtolower($rawEmail) : null;
        // Un contact invalide ne devient jamais une adresse de livraison.
        // Le compte réservé pourra être corrigé par l'équipe avant activation.
        $email = $validEmail ?? 'eau-togo-source-'.$source['row'].'@geves.invalid';
        $user = User::query()->whereRaw('LOWER(email) = ?', [$email])->first();
        if ($user !== null) {
            if ($validEmail === null && ($user->meta['import_source'] ?? null) !== self::SOURCE) {
                throw new RuntimeException("Adresse réservée déjà utilisée pour la ligne {$source['row']}.");
            }

            return $user;
        }

        $phone = Phone::normalize((string) $source['phone']);
        if (! Phone::usable($phone) || User::query()->where('phone', $phone)->exists()) {
            $phone = null;
        }

        $user = new User;
        $user->forceFill([
            'name' => trim($source['given_name'].' '.$source['surname']),
            'first_name' => trim((string) $source['given_name']),
            'last_name' => trim((string) $source['surname']),
            'email' => $email,
            'phone' => $phone,
            'grade' => trim((string) $source['grade']),
            'affiliation' => trim((string) $source['affiliation']),
            'country' => trim((string) $source['country']),
            'password' => Str::password(48),
            'must_reset_password' => true,
            'is_active' => true,
            'access_level' => User::ACCESS_USER,
            'meta' => ['import_source' => self::SOURCE, 'source_row' => $source['row'], 'contact_email_needs_review' => $validEmail === null],
        ])->save();

        return $user;
    }

    /** @param array<string, mixed> $response @param array<string, mixed> $source */
    private function submission(
        Event $event,
        Participant $participant,
        array $response,
        array $source,
        ZipArchive $zip,
        int $number
    ): void {
        $reference = sprintf('EAU26-%03d', $number);
        $extension = strtolower(pathinfo((string) $source['file_name'], PATHINFO_EXTENSION));
        if (! in_array($extension, ['doc', 'docx'], true)) {
            throw new RuntimeException("Extension Word inattendue pour {$reference}.");
        }

        $path = EventStorage::submissions($event)."/{$reference}.{$extension}";
        $disk = Storage::disk('public');
        if (! $disk->exists($path)) {
            $bytes = $zip->getFromIndex((int) $source['file_index']);
            if ($bytes === false || ! $disk->put($path, $bytes)) {
                throw new RuntimeException("Impossible de stocker la pièce Word {$reference}.");
            }
        } elseif (hash('sha256', (string) $disk->get($path)) !== $source['file_sha256']) {
            throw new RuntimeException("Une pièce Word différente existe déjà pour {$reference}.");
        }

        $existing = Submission::query()
            ->where('event_id', $event->id)
            ->where('ref_code', $reference)
            ->first();
        if ($existing !== null) {
            if (($existing->meta['import_source'] ?? null) !== self::SOURCE
                || (int) ($existing->meta['source_row'] ?? 0) !== (int) $response['row']) {
                throw new RuntimeException("La référence {$reference} appartient à une autre soumission.");
            }
        }

        $email = filter_var($participant->email, FILTER_VALIDATE_EMAIL) ? $participant->email : null;
        $authorName = trim($participant->first_name.' '.$participant->last_name);
        $submission = $existing ?? Submission::create([
            'event_id' => $event->id,
            'participant_id' => $participant->id,
            'ref_code' => $reference,
            'title' => trim((string) $source['title']),
            'abstract' => trim((string) $source['abstract']),
            'keywords' => trim((string) $source['keywords']),
            'track' => trim((string) $source['track']),
            'type' => $response['communication'] === 'Poster' ? 'poster' : 'oral',
            'presentation_mode' => $response['presentation_mode'] === 'Distantiel' ? 'online' : 'onsite',
            'status' => 'submitted',
            'revision_of' => 0,
            'version' => 1,
            'file_url' => $disk->url($path),
            'authors' => [[
                'name' => $authorName,
                'email' => $email,
                'affiliation' => $participant->institution,
                'corresponding' => true,
            ]],
            'meta' => [
                'import_source' => self::SOURCE,
                'source_row' => $response['row'],
                'source_abstract_number' => $source['number'],
                'google_drive_url' => $source['drive_url'],
                'coauthors_raw' => $source['coauthors_raw'],
                'original_file_name' => $source['file_name'],
                'file_sha256' => $source['file_sha256'],
                'presentation_mode' => $response['presentation_mode'],
                'preferred_payment_method' => $response['preferred_payment_method'],
                'source_email' => $response['email'],
            ],
            'created_at' => $response['timestamp'],
        ]);

        if ($existing !== null && ! in_array($existing->presentation_mode, ['online', 'onsite'], true)) {
            $existing->update(['presentation_mode' => $response['presentation_mode'] === 'Distantiel' ? 'online' : 'onsite']);
        }

        $authorLink = SubmissionAuthor::firstOrCreate([
            'submission_id' => $submission->id,
            'author_index' => 0,
        ], [
            'event_id' => $event->id,
            'user_id' => $participant->user_id,
            'role' => 'corresponding',
            'name' => $authorName,
            'email' => $email,
            'phone' => $participant->phone,
            'affiliation' => $participant->institution,
            'match_type' => $participant->user_id ? 'self' : null,
            'status' => $participant->user_id ? 'linked' : 'unmatched',
        ]);
        if ($authorLink->user_id === null) {
            $authorLink->update(['user_id' => $participant->user_id, 'match_type' => 'self', 'status' => 'linked']);
        } elseif ((int) $authorLink->user_id !== (int) $participant->user_id) {
            throw new RuntimeException("L'auteur de {$reference} est déjà lié à un autre compte.");
        }
    }
}
